WITH deduped AS (SELECT id, started_at FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device, browser ORDER BY started_at DESC NULLS FIRST, id) AS dedup_rank FROM sessions) ranked WHERE dedup_rank = 1) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, MAX(started_at) AS ended_at, MIN(started_at) AS first_started_at, MAX(started_at) AS last_started_at, MIN(started_at) AS started_at, COUNT(*) AS num_rows FROM deduped GROUP BY DATE_TRUNC('WEEK', started_at) ORDER BY week_start;
